  INSERT INTO Interactions (Id, Medicine1Id, Medicine2Id, Severity, Description, Advice) VALUES
  (1, 1, 2, N'Mild', N'Both painkillers together may increase stomach irritation', N'Take with food. Avoid long-term combined use.'),
  (2, 1, 8, N'Mild', N'Paracetamol with Aspirin may affect liver at high doses', N'Do not exceed recommended doses of either.'),
  (3, 2, 8, N'Dangerous', N'Ibuprofen and Aspirin together significantly increase risk of stomach bleeding and ulcers', N'Do NOT take together. Consult doctor for alternative.'),
  (4, 3, 1, N'Safe', N'No significant interaction between Augmentin and Panadol', N'Safe to take together as prescribed.'),
  (5, 4, 8, N'Dangerous', N'Ciprofloxacin with Aspirin may increase bleeding risk', N'Avoid combining. Consult your doctor.'),
  (6, 5, 2, N'Mild', N'Cetirizine may enhance drowsiness effect of Ibuprofen', N'Be cautious when driving or operating machinery.'),
  (7, 7, 2, N'Mild', N'Ibuprofen may reduce blood pressure lowering effect of Amlodipine', N'Monitor blood pressure regularly.'),
  (8, 9, 2, N'Mild', N'Ibuprofen may affect blood sugar control of Metformin', N'Monitor blood sugar levels closely.'),
  (9, 10, 2, N'Mild', N'Ibuprofen may worsen nausea side effect of Domperidone', N'Take with food to minimize stomach upset.'),
  (10, 11, 8, N'Mild', N'Omeprazole may reduce absorption of Aspirin', N'Take 2 hours apart.'),
  (11, 13, 2, N'Mild', N'Disprin and Brufen both are NSAIDs - increased stomach risk', N'Do not combine regularly. Risk of GI bleeding.'),
  (12, 16, 8, N'Dangerous', N'Diclofenac with Aspirin greatly increases risk of GI bleeding', N'Avoid combination. Risk of stomach ulcers and bleeding.'),
  (13, 19, 2, N'Dangerous', N'Panadeine with Brufen - double painkiller risk to stomach', N'Avoid combining. Use only as prescribed.'),
  (14, 26, 8, N'Mild', N'Arthrotec contains Diclofenac - similar risk with Aspirin', N'Monitor for stomach pain. Take with food.'),
  (15, 30, 8, N'Mild', N'Brufen Syrup with Aspirin - NSAID combination risk', N'Avoid for children without doctor advice.'),
  (16, 31, 8, N'Mild', N'Adalat with Aspirin - monitor for low blood pressure', N'Rise slowly from sitting position.'),
  (17, 42, 8, N'Mild', N'Cataflam (Diclofenac) with Aspirin - GI bleeding risk', N'Take with food. Short duration only.'),
  (18, 47, 8, N'Dangerous', N'Warfarin with Aspirin - SEVERE bleeding risk', N'NEVER combine without direct doctor supervision. Life-threatening.'),
  (19, 48, 8, N'Dangerous', N'Clopivas with Aspirin - increased bleeding risk', N'Do NOT combine. High risk of serious bleeding.'),
  (20, 47, 2, N'Dangerous', N'Warfarin with Ibuprofen - increased bleeding risk', N'Avoid Ibuprofen. Use Paracetamol instead for pain.'),
  (21, 48, 2, N'Dangerous', N'Clopivas with Ibuprofen - bleeding risk increases', N'Avoid Ibuprofen. Consult doctor for safe pain relief.'),
  (22, 47, 1, N'Mild', N'Warfarin with Paracetamol - monitor INR levels', N'Safe in normal doses. Regular blood tests recommended.'),
  (23, 49, 2, N'Dangerous', N'Alprazolam with Ibuprofen - enhanced drowsiness and confusion', N'Avoid driving. Risk of impaired coordination.'),
  (24, 49, 1, N'Mild', N'Alprazolam with Paracetamol - increased drowsiness', N'Take at bedtime. Avoid activities requiring alertness.'),
  (25, 6, 49, N'Mild', N'Claritin with Alprazolam - may increase sedation', N'Be cautious. May feel more drowsy than usual.'),
  (26, 14, 2, N'Mild', N'Fexo with Ibuprofen - may increase headache', N'Stay hydrated. Take with food.'),
  (27, 4, 47, N'Mild', N'Ciprocin with Warfarin - may enhance anticoagulant effect', N'Monitor INR closely. Report any bleeding immediately.'),
  (28, 3, 47, N'Mild', N'Augmentin with Warfarin - may increase INR', N'Regular blood monitoring recommended.'),
  (29, 27, 47, N'Dangerous', N'Flagyl with Warfarin - significantly increased bleeding risk', N'Avoid if possible. Requires close INR monitoring.'),
  (30, 33, 49, N'Mild', N'Dilantin with Alprazolam - increased drowsiness', N'Avoid driving. Take at night if possible.'),
  (31, 47, 51, N'Dangerous', N'Nurofen (ibuprofen) significantly increases bleeding risk when combined with Warfarin', N'Avoid this combination. Use Paracetamol for pain instead and consult your doctor.'),
  (32, 8, 51, N'Dangerous', N'Loprin (aspirin) plus Nurofen (ibuprofen) together greatly increase stomach bleeding and ulcer risk', N'Avoid combining two NSAIDs. Take only one, with food, for the shortest time.'),
  (33, 8, 52, N'Dangerous', N'Loprin (aspirin) with Arcoxia (etoricoxib) raises the risk of gastric bleeding and kidney strain', N'Do not combine. Ask your doctor for a safer pain option such as Paracetamol.'),
  (34, 1, 50, N'Mild', N'Ponstan and Panadol together may irritate the stomach; both are painkillers with different actions', N'Occasional combined use is usually okay with food. Avoid long-term use together.'),
  (35, 19, 1, N'Major', N'Panadeine already contains Paracetamol — adding Panadol can cause accidental Paracetamol overdose and liver damage', N'Do not take both. Count all Paracetamol-containing medicines toward the 4g/day maximum.'),
  (36, 59, 60, N'Mild', N'Cozar (losartan) with Lasix (furosemide) can lower blood pressure too much and deplete potassium', N'Monitor blood pressure and potassium levels. Stay hydrated and report dizziness.'),
  (37, 62, 8, N'Major', N'Loprin (aspirin) can raise blood sugar control issues and mask hypoglycemia symptoms in diabetics taking Amaryl', N'Monitor blood sugar closely. Watch for unusual sweating, tremor, or confusion.'),
  (38, 66, 3, N'Major', N'Pan 40 (pantoprazole) reduces stomach acidity needed for Augmentin absorption, lowering antibiotic effectiveness', N'Take Augmentin 2 hours before or after Pan 40. Complete the full antibiotic course.'),
  (39, 56, 57, N'Dangerous', N'Telfast plus Atarax combines antihistamine effects causing severe drowsiness and impaired coordination', N'Avoid taking together. Prefer a single non-drowsy antihistamine like Telfast alone.'),
  (40, 58, 57, N'Dangerous', N'Benadryl with Atarax causes additive sedation, dry mouth, and risk of confusion in elderly patients', N'Avoid this combination, especially in older adults. Consult your doctor.'),
  (41, 53, 47, N'Major', N'Klaricid (clarithromycin) strongly increases Warfarin levels, raising bleeding risk', N'Requires INR monitoring and possible Warfarin dose reduction. Report any bruising or bleeding.'),
  (42, 55, 47, N'Major', N'Doxy-1 (doxycycline) can enhance Warfarin effect and increase bleeding risk', N'Monitor for unusual bleeding. Maintain consistent vitamin K intake from food.'),
  (43, 52, 48, N'Major', N'Arcoxia (etoricoxib) with Clopivas (clopidogrel) increases gastrointestinal bleeding risk', N'Use the lowest Arcoxia dose for the shortest time. Take with food and gastroprotection.'),
  (44, 66, 48, N'Major', N'Pan 40 (pantoprazole) reduces activation of Clopivas (clopidogrel), weakening its anti-clotting effect', N'Consider replacing Pan 40 with Pantoprazole alternatives like Ranitidine, or use Clopidogrel at a different time. Discuss with cardiologist.'),
  (45, 49, 57, N'Dangerous', N'Alprazolam with Atarax causes dangerous combined sedation, breathing depression, and falls risk', N'Avoid combining. Never increase doses of either without medical supervision.');
