-- PillWise full seed: 8 categories, 79 medicines, 45 interactions.
-- Matches the live database exactly (same IDs as the API's seeded data).
-- Safe to run once; each block is skipped if IDs already exist.

IF NOT EXISTS (SELECT 1 FROM Categories WHERE Id = 1)
BEGIN
  SET IDENTITY_INSERT Categories ON;
  SET IDENTITY_INSERT Categories OFF;
END
GO

IF NOT EXISTS (SELECT 1 FROM Medicines WHERE Id = 1)
BEGIN
  SET IDENTITY_INSERT Medicines ON;
  SET IDENTITY_INSERT Medicines OFF;
END
GO

IF NOT EXISTS (SELECT 1 FROM Interactions WHERE Id = 1)
BEGIN
  SET IDENTITY_INSERT Interactions ON;
  SET IDENTITY_INSERT Interactions OFF;
END
GO
